"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function stripFields(instance, fields) {
  const data = { ...instance.get() };

  for (const field of fields) {
    delete data[field];
  }

  return data;
}

class SerializableModel extends Model {
  toJSON() {
    return stripFields(this, this.constructor.hiddenFields ?? []);
  }
}

class User extends SerializableModel {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }
}

User.hiddenFields = ["id", "updatedAt", "createdAt"];

class Article extends SerializableModel {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "cascade" });
  }
}

Article.hiddenFields = ["id", "userId"];

class Comment extends SerializableModel {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }
}

Comment.hiddenFields = ["articleId", "userId"];

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();
Comment.associate();

module.exports = { sequelize, User, Article, Comment };

const { User, Article, Comment } = require("./models");

const SEED = {
  username: "u1",
  slug: "a1",
  comments: ["c1", "c2"],
};

const COMMENT_INCLUDE = [
  { model: User, as: "author", attributes: ["username"] },
];

async function seedDemoData() {
  const [user] = await User.findOrCreate({
    where: { username: SEED.username },
    defaults: { username: SEED.username },
  });

  const [article] = await Article.findOrCreate({
    where: { slug: SEED.slug },
    defaults: { slug: SEED.slug, userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count === 0) {
    await Comment.bulkCreate(
      SEED.comments.map((body) => ({
        body,
        articleId: article.id,
        userId: user.id,
      })),
    );
  }
}

async function getCommentsBySlug(slug) {
  const article = await Article.findOne({ where: { slug } });
  if (!article) {
    return null;
  }

  return article.getComments({
    include: COMMENT_INCLUDE,
  });
}

module.exports = {
  getCommentsBySlug,
  seedDemoData,
};

